function buildDataSheet(sheet, title, subtitle, rows, tableName) {
  sheet.showGridLines = false;
  sheet.getRange('A2').values = [[title]];
  sheet.getRange('A2').format.font = { name: font, size: 16, bold: true, color: '#10264F' };
  sheet.getRange('A3').values = [[subtitle]];
  sheet.getRange('A3:O3').merge();
  sheet.getRange('A3').format.font = { name: font, size: 10, italic: true, color: '#596579' };
  sheet.getRange('A5:O5').values = [columns];
  sheet.getRange(`A6:O${rows.length + 5}`).values = rows;
  const used = sheet.getRange(`A5:O${rows.length + 5}`);
  used.format.font = { name: font, size: 10, color: '#202A3A' };
  used.format.verticalAlignment = 'top';
  used.format.wrapText = true;
  sheet.getRange('A5:O5').format = {
    fill: '#10264F',
    font: { name: font, size: 10, bold: true, color: '#FFFFFF' },
    horizontalAlignment: 'center', verticalAlignment: 'center', wrapText: true,
    borders: { preset: 'inside', style: 'thin', color: '#FFFFFF' },
  };
  sheet.getRange(`A6:O${rows.length + 5}`).format.borders = { insideHorizontal: { style: 'thin', color: '#D8DEE8' } };
  sheet.getRange(`K6:K${rows.length + 5}`).conditionalFormats.add('containsText', { text: 'Block', format: { fill: '#FCE8E6', font: { color: '#A61B1B', bold: true } } });
  sheet.getRange(`K6:K${rows.length + 5}`).conditionalFormats.add('containsText', { text: 'Allow', format: { fill: '#E6F4EA', font: { color: '#176B32', bold: true } } });
  sheet.getRange(`N6:N${rows.length + 5}`).dataValidation = { rule: { type: 'list', values: ['Not Run','Pass','Fail','Blocked','N/A'] } };
  sheet.getRange(`N6:N${rows.length + 5}`).conditionalFormats.add('containsText', { text: 'Pass', format: { fill: '#E6F4EA', font: { color: '#176B32', bold: true } } });
  sheet.getRange(`N6:N${rows.length + 5}`).conditionalFormats.add('containsText', { text: 'Fail', format: { fill: '#FCE8E6', font: { color: '#A61B1B', bold: true } } });
  sheet.getRange(`N6:N${rows.length + 5}`).conditionalFormats.add('containsText', { text: 'Not Run', format: { fill: '#EEF1F5', font: { color: '#596579' } } });
  sheet.freezePanes.freezeRows(5);
  sheet.freezePanes.freezeColumns(3);
  const widths = [14,20,25,38,14,12,38,52,28,55,20,44,34,16,30];
  widths.forEach((width,index) => sheet.getRangeByIndexes(0,index,rows.length+5,1).format.columnWidth = width);
  sheet.getRange('2:2').format.rowHeight = 24;
  sheet.getRange('3:3').format.rowHeight = 28;
  sheet.getRange('5:5').format.rowHeight = 36;
  sheet.getRange(`6:${rows.length + 5}`).format.rowHeight = 82;
  const table = sheet.tables.add(`A5:O${rows.length + 5}`, true, tableName);
  table.style = 'TableStyleMedium2';
  table.showBandedRows = true;
  table.showFilterButton = true;
}

