workbook.recalculate();
await fs.mkdir(outDir,{recursive:true});
const file = await SpreadsheetFile.exportXlsx(workbook);
await file.save(`${outDir}/BrgySync_Test_Case_Suite.xlsx`);

const checks = [];
for (const [sheetName, range] of [['Summary','A2:F17'],['Admin tests','A2:O12'],['Resident tests','A2:O12'],['Access controls','A2:O12'],['Execution guide','A2:B13']]) {
  const inspected = await workbook.inspect({kind:'table',range:`${sheetName}!${range}`,include:'values,formulas',tableMaxRows:20,tableMaxCols:16,maxChars:8000});
  checks.push({sheetName,inspection:inspected.ndjson});
  const preview = await workbook.render({sheetName,range,scale:1,format:'png'});
  await fs.writeFile(`${outDir}/${sheetName.replaceAll(' ','_')}.png`,new Uint8Array(await preview.arrayBuffer()));
}
const errors = await workbook.inspect({kind:'match',searchTerm:'#REF!|#DIV/0!|#VALUE!|#NAME\\?|#N/A|#NUM!|#NULL!|#SPILL!|#CALC!',options:{useRegex:true,maxResults:300},summary:'final formula error scan'});
await fs.writeFile(`${outDir}/verification.json`,JSON.stringify({counts:{admin:admin.length,resident:resident.length,access:access.length,total:admin.length+resident.length+access.length},checks,errorScan:errors.ndjson},null,2));
console.log(JSON.stringify({admin:admin.length,resident:resident.length,access:access.length,total:admin.length+resident.length+access.length,output:`${outDir}/BrgySync_Test_Case_Suite.xlsx`}));
